// Signed arbitrary precision integers. Base 2^32, little-endian magnitude.
struct RuskBigInt {
    bool negative=false;
    std::vector<std::uint32_t> words;
    void trim(){while(!words.empty()&&words.back()==0)words.pop_back();if(words.empty())negative=false;}
    RuskBigInt()=default;
    explicit RuskBigInt(std::int64_t n){negative=n<0;auto u=negative?std::uint64_t(0)-static_cast<std::uint64_t>(n):static_cast<std::uint64_t>(n);if(u){words.push_back(static_cast<std::uint32_t>(u));if(u>>32)words.push_back(static_cast<std::uint32_t>(u>>32));}}
    static int magnitude_compare(const RuskBigInt& a,const RuskBigInt& b){if(a.words.size()!=b.words.size())return a.words.size()<b.words.size()?-1:1;for(auto i=a.words.size();i>0;--i)if(a.words[i-1]!=b.words[i-1])return a.words[i-1]<b.words[i-1]?-1:1;return 0;}
    friend int compare(const RuskBigInt& a,const RuskBigInt& b){if(a.negative!=b.negative)return a.negative?-1:1;auto c=magnitude_compare(a,b);return a.negative?-c:c;}
    friend bool operator==(const RuskBigInt&a,const RuskBigInt&b){return a.negative==b.negative&&a.words==b.words;}
    friend bool operator!=(const RuskBigInt&a,const RuskBigInt&b){return !(a==b);}
    friend bool operator<(const RuskBigInt&a,const RuskBigInt&b){return compare(a,b)<0;}
    friend bool operator<=(const RuskBigInt&a,const RuskBigInt&b){return compare(a,b)<=0;}
    friend bool operator>(const RuskBigInt&a,const RuskBigInt&b){return compare(a,b)>0;}
    friend bool operator>=(const RuskBigInt&a,const RuskBigInt&b){return compare(a,b)>=0;}
    static RuskBigInt magnitude_add(const RuskBigInt&a,const RuskBigInt&b){RuskBigInt r;std::uint64_t carry=0;for(std::size_t i=0;i<std::max(a.words.size(),b.words.size())||carry;++i){auto s=carry+(i<a.words.size()?a.words[i]:0)+(i<b.words.size()?b.words[i]:0);r.words.push_back(static_cast<std::uint32_t>(s));carry=s>>32;}return r;}
    static RuskBigInt magnitude_sub(const RuskBigInt&a,const RuskBigInt&b){RuskBigInt r;std::uint64_t borrow=0;for(std::size_t i=0;i<a.words.size();++i){std::uint64_t x=a.words[i],y=(i<b.words.size()?b.words[i]:0)+borrow;r.words.push_back(static_cast<std::uint32_t>(x-y));borrow=x<y;}r.trim();return r;}
    friend RuskBigInt operator-(RuskBigInt a){if(!a.words.empty())a.negative=!a.negative;return a;}
    friend RuskBigInt operator+(const RuskBigInt&a,const RuskBigInt&b){RuskBigInt r;if(a.negative==b.negative){r=magnitude_add(a,b);r.negative=a.negative;}else if(magnitude_compare(a,b)>=0){r=magnitude_sub(a,b);r.negative=a.negative;}else{r=magnitude_sub(b,a);r.negative=b.negative;}r.trim();return r;}
    friend RuskBigInt operator-(const RuskBigInt&a,const RuskBigInt&b){return a+(-b);}
    friend RuskBigInt operator*(const RuskBigInt&a,const RuskBigInt&b){RuskBigInt r;r.words.resize(a.words.size()+b.words.size());for(std::size_t i=0;i<a.words.size();++i){std::uint64_t carry=0;for(std::size_t j=0;j<b.words.size();++j){auto s=std::uint64_t(a.words[i])*b.words[j]+r.words[i+j]+carry;r.words[i+j]=static_cast<std::uint32_t>(s);carry=s>>32;}if(!b.words.empty())r.words[i+b.words.size()]=static_cast<std::uint32_t>(carry);}r.negative=a.negative!=b.negative;r.trim();return r;}
    std::size_t bits()const{if(words.empty())return 0;auto x=words.back();unsigned n=0;while(x){++n;x>>=1;}return (words.size()-1)*32+n;}
    // Binary long division of magnitudes; signs are adjusted for floor division.
    static std::pair<RuskBigInt,RuskBigInt> divmod(const RuskBigInt&a,const RuskBigInt&b,Loc loc){if(b.words.empty())fail(loc,"division by zero");RuskBigInt q,r;q.words.resize(a.words.size());for(auto i=a.bits();i>0;--i){std::uint64_t carry=(a.words[(i-1)/32]>>((i-1)%32))&1u;for(auto& w:r.words){auto v=(std::uint64_t(w)<<1)|carry;w=static_cast<std::uint32_t>(v);carry=v>>32;}if(carry)r.words.push_back(static_cast<std::uint32_t>(carry));if(magnitude_compare(r,b)>=0){r=magnitude_sub(r,b);q.words[(i-1)/32]|=std::uint32_t(1)<<((i-1)%32);}}q.trim();if(a.negative!=b.negative&&!r.words.empty()){q=magnitude_add(q,RuskBigInt(1));r=magnitude_sub(b,r);}q.negative=(a.negative!=b.negative)&&!q.words.empty();r.negative=b.negative&&!r.words.empty();return {q,r};}
    void multiply_small(std::uint32_t n){std::uint64_t carry=0;for(auto&w:words){auto s=std::uint64_t(w)*n+carry;w=static_cast<std::uint32_t>(s);carry=s>>32;}if(carry)words.push_back(static_cast<std::uint32_t>(carry));trim();}
    std::uint32_t divide_small(std::uint32_t n){std::uint64_t carry=0;for(auto i=words.size();i>0;--i){auto s=(carry<<32)|words[i-1];words[i-1]=static_cast<std::uint32_t>(s/n);carry=s%n;}trim();return static_cast<std::uint32_t>(carry);}
    static RuskBigInt parse(const std::string&s,Loc loc){RuskBigInt r;std::size_t i=0;bool neg=false;if(!s.empty()&&(s[0]=='-'||s[0]=='+')){neg=s[0]=='-';++i;}if(i==s.size())fail(loc,"invalid BigInt input");for(;i<s.size();++i){if(s[i]<'0'||s[i]>'9')fail(loc,"invalid BigInt input");r.multiply_small(10);r=magnitude_add(r,RuskBigInt(s[i]-'0'));}r.negative=neg&&!r.words.empty();return r;}
    std::string str()const{if(words.empty())return "0";auto n=*this;n.negative=false;std::vector<std::uint32_t> parts;while(!n.words.empty())parts.push_back(n.divide_small(1000000000));auto out=(negative?"-":"")+std::to_string(parts.back());for(auto i=parts.size()-1;i>0;--i){auto part=std::to_string(parts[i-1]);out+=std::string(9-part.size(),'0')+part;}return out;}
    std::int64_t to_int(Loc loc)const{if(words.size()>2)fail(loc,"integer conversion out of range");std::uint64_t n=words.empty()?0:words[0];if(words.size()==2)n|=std::uint64_t(words[1])<<32;const auto limit=std::uint64_t(1)<<63;if(n>(negative?limit:limit-1))fail(loc,"integer conversion out of range");if(negative&&n==limit)return std::numeric_limits<std::int64_t>::min();return negative?-static_cast<std::int64_t>(n):static_cast<std::int64_t>(n);}
    static RuskBigInt shift(RuskBigInt a,std::int64_t n,bool left,Loc loc){auto amount=n<0?std::uint64_t(0)-static_cast<std::uint64_t>(n):static_cast<std::uint64_t>(n);if(n<0)left=!left;if(a.words.empty()||!amount)return a;auto whole=amount/32;auto part=static_cast<unsigned>(amount%32);if(left){if(whole>a.words.max_size()-a.words.size()-1)fail(loc,"shift too large");std::vector<std::uint32_t> out(static_cast<std::size_t>(whole),0);std::uint64_t carry=0;for(auto w:a.words){auto s=(std::uint64_t(w)<<part)|carry;out.push_back(static_cast<std::uint32_t>(s));carry=s>>32;}if(carry)out.push_back(static_cast<std::uint32_t>(carry));a.words=std::move(out);}else{bool lost=false;if(whole>=a.words.size())return RuskBigInt(a.negative?-1:0);for(std::size_t i=0;i<whole;++i)lost|=a.words[i]!=0;if(part)lost|=(a.words[whole]&((std::uint32_t(1)<<part)-1))!=0;std::vector<std::uint32_t> out;for(std::size_t i=static_cast<std::size_t>(whole);i<a.words.size();++i){std::uint64_t s=a.words[i];if(part&&i+1<a.words.size())s|=std::uint64_t(a.words[i+1])<<32;out.push_back(static_cast<std::uint32_t>(s>>part));}bool neg=a.negative;a.words=std::move(out);a.trim();if(neg&&lost){a.negative=false;a=magnitude_add(a,RuskBigInt(1));a.negative=true;}else a.negative=neg&&!a.words.empty();}a.trim();return a;}
    static RuskBigInt bitwise(const RuskBigInt&a,const RuskBigInt&b,char op){auto size=std::max(a.words.size(),b.words.size())+1;auto twos=[&](const RuskBigInt&x){auto v=x.words;v.resize(size);if(x.negative){std::uint64_t carry=1;for(auto&w:v){auto s=std::uint64_t(~w)+carry;w=static_cast<std::uint32_t>(s);carry=s>>32;}}return v;};auto av=twos(a),bv=twos(b);RuskBigInt r;r.words.resize(size);for(std::size_t i=0;i<size;++i)r.words[i]=op=='&'?(av[i]&bv[i]):op=='|'?(av[i]|bv[i]):(av[i]^bv[i]);r.negative=(r.words.back()>>31)!=0;if(r.negative){std::uint64_t carry=1;for(auto&w:r.words){auto s=std::uint64_t(~w)+carry;w=static_cast<std::uint32_t>(s);carry=s>>32;}}r.trim();return r;}
};
